<?php
require_once __DIR__.'/config.php'; require_page_permission('contracts');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('INSERT INTO contracts(unit_id,person_id,type,start_date,end_date,amount,deposit_amount,notes) VALUES(?,?,?,?,?,?,?,?)')->execute([(int)post('unit_id'),(int)post('person_id'),post('type','rent'),post('start_date'),post('end_date')?:null,(float)post('amount',0),(float)post('deposit_amount',0),trim(post('notes'))?:null]);flash('قرارداد ثبت شد.');redirect('contracts.php');}
if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM contracts WHERE id=?')->execute([(int)$_GET['delete']]);flash('قرارداد حذف شد.');redirect('contracts.php');}$units=$pdo->query('SELECT id,unit_no FROM units ORDER BY unit_no')->fetchAll();$persons=$pdo->query('SELECT id,first_name,last_name FROM persons ORDER BY last_name')->fetchAll();$rows=$pdo->query("SELECT c.*,u.unit_no,CONCAT(p.first_name,' ',p.last_name) person_name FROM contracts c JOIN units u ON u.id=c.unit_id JOIN persons p ON p.id=c.person_id ORDER BY c.id DESC")->fetchAll();page_header('قراردادها');
?><div class="toolbar"><h1>قراردادها</h1></div><form class="form" method="post"><?=csrf_field()?><div class="grid"><label>واحد<select name="unit_id" required><?php foreach($units as $u):?><option value="<?=$u['id']?>">واحد <?=e($u['unit_no'])?></option><?php endforeach;?></select></label><label>طرف قرارداد<select name="person_id" required><?php foreach($persons as $p):?><option value="<?=$p['id']?>"><?=e($p['first_name'].' '.$p['last_name'])?></option><?php endforeach;?></select></label><label>نوع<select name="type"><option value="rent">اجاره</option><option value="sale">فروش</option></select></label><label>تاریخ شروع<input type="date" name="start_date" required value="<?=date('Y-m-d')?>"></label><label>تاریخ پایان<input type="date" name="end_date"></label><label>مبلغ<input type="number" step="0.01" name="amount"></label><label>ودیعه<input type="number" step="0.01" name="deposit_amount"></label><label style="grid-column:1/-1">توضیحات<textarea name="notes"></textarea></label></div><div class="actions"><button>ثبت قرارداد</button></div></form><h2>لیست قراردادها</h2><div class="table-wrap"><table class="table"><tr><th>واحد</th><th>طرف قرارداد</th><th>نوع</th><th>شروع</th><th>پایان</th><th>مبلغ</th><th>عملیات</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['unit_no'])?></td><td><?=e($r['person_name'])?></td><td><?=e($r['type'])?></td><td><?=$r['start_date']?></td><td><?=$r['end_date']?></td><td><?=money($r['amount'])?></td><td><a class="button danger" onclick="return confirm('حذف شود؟')" href="contracts.php?delete=<?=$r['id']?>">حذف</a></td></tr><?php endforeach;?></table></div><?php page_footer();?>
